(71, 6, 'daha_once_hangi_tur_projelerde_gorev_ald_n_z', 'Daha önce hangi tür projelerde görev aldınız?', 'Üretim ve montaj aşamalarında temel oluşturan alüminyum, çelik ve cam konstrüksiyon detaylarının 2D / 3D modelleme çalışmalarını yürüttüm', '2026-02-10 10:58:31'),
(72, 6, 'proje_surecinde_hangi_asamalarda_kesif_tasar_m_gelistirme_uygulama_saha_takibi_vb_daha_etkin_rol_al_rs_n_z', 'Proje sürecinde hangi aşamalarda (keşif, tasarım geliştirme, uygulama, saha takibi vb.) daha etkin rol alırsınız?', 'İnşaat sahasında yürütülen proje yönetim süreçlerini yerinde takip ederek, iş programlarının koordinasyonu ve kontrolüne katkı sağladım.', '2026-02-10 10:58:31'),
(73, 6, 'aktif_olarak_kulland_g_n_z_tasar_m_ve_cizim_programlar_n_belirtiniz', 'Aktif olarak kullandığınız tasarım ve çizim programlarını belirtiniz.', 'AUTOCAD, SOLİDWORKS, REVIT, 3DS MAX, BLENDER, RHINO, SKETCHUP, ADOBE PHOTOSHOP, ADOBE ILLUSTRATOR.', '2026-02-10 10:58:31'),
(74, 6, 'teknik_detay_uygulama_cizimi_veya_uretim_surecine_yonelik_bilgi_ve_deneyiminiz_var_m', 'Teknik detay, uygulama çizimi veya üretim sürecine yönelik bilgi ve deneyiminiz var mı?', 'EVET', '2026-02-10 10:58:31'),
(75, 6, 'farkl_departmanlarla_uretim_montaj_saha_sat_n_alma_vb_proje_koordinasyonunu_nas_l_yurutursunuz', 'Farklı departmanlarla (üretim, montaj, saha, satın alma vb.) proje koordinasyonunu nasıl yürütürsünüz?', 'Detaylara gösterdiğim özen, araştırmaya  olan ilgim ve kullanıcı odaklı yaklaşımım sayesinde her projede işlevselliği ve tasarımı dengeli bir biçimde ele alırım.', '2026-02-10 10:58:31'),
(76, 6, 'proje_surecinde_kars_last_g_n_z_bir_zorlukta_nas_l_bir_cozum_yaklas_m_benimsersiniz', 'Proje sürecinde karşılaştığınız bir zorlukta nasıl bir çözüm yaklaşımı benimsersiniz?', 'ekip yaklaşımım, anında müdehale ve hızlı aksiyon alarak.', '2026-02-10 10:58:31'),
