(215, 11, 'daha_once_hangi_tur_projelerde_gorev_ald_n_z', 'Daha önce hangi tür projelerde görev aldınız?', 'Anahtar teslim villa-konut projelerinde, ahşap konstrüksiyon-ahşap deck projelerinde yer aldım. Yer aldığım projelerin tasarım, malzeme seçimi ve sunumu, taşeron belirleme, hakediş, işveren toplantıları gibi tüm süreçlerinde bulundum.', '2026-02-11 11:52:27'),
(216, 11, 'proje_surecinde_hangi_asamalarda_kesif_tasar_m_gelistirme_uygulama_saha_takibi_vb_daha_etkin_rol_al_rs_n_z', 'Proje sürecinde hangi aşamalarda (keşif, tasarım geliştirme, uygulama, saha takibi vb.) daha etkin rol alırsınız?', 'Uygulama, saha takip', '2026-02-11 11:52:27'),
(217, 11, 'aktif_olarak_kulland_g_n_z_tasar_m_ve_cizim_programlar_n_belirtiniz', 'Aktif olarak kullandığınız tasarım ve çizim programlarını belirtiniz.', 'Autocad, sketchup', '2026-02-11 11:52:27'),
(218, 11, 'teknik_detay_uygulama_cizimi_veya_uretim_surecine_yonelik_bilgi_ve_deneyiminiz_var_m', 'Teknik detay, uygulama çizimi veya üretim sürecine yönelik bilgi ve deneyiminiz var mı?', 'Evet', '2026-02-11 11:52:27'),
(219, 11, 'farkl_departmanlarla_uretim_montaj_saha_sat_n_alma_vb_proje_koordinasyonunu_nas_l_yurutursunuz', 'Farklı departmanlarla (üretim, montaj, saha, satın alma vb.) proje koordinasyonunu nasıl yürütürsünüz?', 'Projeye uygun doğru malzeme seçimi ve malzeme temini ile başlayarak uygulama ekip ile koordine olurum. İş programıyla uygulama sırasına göre saha programını oluştururum.', '2026-02-11 11:52:27'),
