(638, 26, 'daha_once_hangi_tur_projelerde_gorev_ald_n_z', 'Daha önce hangi tür projelerde görev aldınız?', 'Dap yapı, invest gibi büyük inşaat firmalarının mermer tezgah ve duvar kaplama işlerini yürütüm.', '2026-02-15 21:03:53'),
(639, 26, 'proje_surecinde_hangi_asamalarda_kesif_tasar_m_gelistirme_uygulama_saha_takibi_vb_daha_etkin_rol_al_rs_n_z', 'Proje sürecinde hangi aşamalarda (keşif, tasarım geliştirme, uygulama, saha takibi vb.) daha etkin rol alırsınız?', 'Tasarım ve saha takibi kısımlarından sorumluydum.', '2026-02-15 21:03:53'),
(640, 26, 'aktif_olarak_kulland_g_n_z_tasar_m_ve_cizim_programlar_n_belirtiniz', 'Aktif olarak kullandığınız tasarım ve çizim programlarını belirtiniz.', 'Autocad, sketchub ve MS ofis programları', '2026-02-15 21:03:53'),
(641, 26, 'teknik_detay_uygulama_cizimi_veya_uretim_surecine_yonelik_bilgi_ve_deneyiminiz_var_m', 'Teknik detay, uygulama çizimi veya üretim sürecine yönelik bilgi ve deneyiminiz var mı?', 'Teknik detay kısmında mobilya sekteründe bulunmamdan dolayı hakimim. Bir ürünün ölçüsünü alıp çizime dökebilecek ve üretime bunu aktarabilecek düzeydeyim çünkü çalıştığım firmada sistem tam olarak böyle işlemekte.', '2026-02-15 21:03:53'),
(642, 26, 'farkl_departmanlarla_uretim_montaj_saha_sat_n_alma_vb_proje_koordinasyonunu_nas_l_yurutursunuz', 'Farklı departmanlarla (üretim, montaj, saha, satın alma vb.) proje koordinasyonunu nasıl yürütürsünüz?', 'O işi bitirene kadar aradaki zinciri güçlü tutarım. Her adımdan haberim olur ve her adımı gerekli merciğlere bildiririm.', '2026-02-15 21:03:53'),
(643, 26, 'proje_surecinde_kars_last_g_n_z_bir_zorlukta_nas_l_bir_cozum_yaklas_m_benimsersiniz', 'Proje sürecinde karşılaştığınız bir zorlukta nasıl bir çözüm yaklaşımı benimsersiniz?', 'Eğer çalıştığım ortamda bu işle ilgili bir kişi varsa ona danışırım. Eğer yok ise bu işin dışardan daha rahat çözeceğim bir kişiye danışırım. Doğru ve net bir bilgi almadan hareket etmem.', '2026-02-15 21:03:53'),
(644, 26, 'gecmiste_cal_st_g_n_z_sirketin_ad', 'Geçmişte çalıştığınız şirketin adı', 'a:1:{i:0;s:15:\"Öztürk mermer\";}', '2026-02-15 21:03:53'),
